def handle(query, state):
    import shlex

    # Virtual filesystem lives in state
    vfs = state.get('files', {})

    def run_cmd(argv):
        """Simulate a tiny set of POSIX commands against the virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]
        if cmd == 'echo':
            return ' '.join(args) + '\n'
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'ls':
            path = args[0] if args else '/'
            entries = sorted([k for k in vfs if k.startswith(path)])
            return '\n'.join(entries) + '\n' if entries else 'ls: no entries\n'
        elif cmd == 'id':
            return 'uid=1000(user) gid=1000(user) groups=1000(user)\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on ';' and run each segment in sequence, concatenating output.
        Does NOT support $() or backtick expansion."""
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    username = (query.get('username') or [''])[0]
    if not username:
        body = 'Usage: ?username=<name>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    # The vulnerable call: username is passed unsanitised into the shell emulator
    output = shell_exec('echo Welcome ' + username)
    return 200, {'Content-Type': 'text/plain'}, output
